		Predicate a2 = cb.equal(ocpm1.get("coverId"), b.get("coverId"));
		effectiveDate.where(a1,a2);

		Predicate n1 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
		Predicate n2 = cb.equal(b.get("coverId") , coverId);
		query.where(n1,n2);
