		res.setCoverageLimit(list.get(0).getCoverageLimit() == null ? "" : df.format(list.get(0).getCoverageLimit()));
		
		// Ofs Details
			List<OfsGridGetRes> gridDetails =  new ArrayList<OfsGridGetRes>();
